from z3 import *
weeks = 5
players = 24
groups = 8
X = [[Int(f'g{w}_{p}') for p in range(players)] for w in range(weeks)]
s = Solver()
for w in range(weeks):
    for p in range(players):
        s.add(And(X[w][p] >= 0, X[w][p] < groups))
for w in range(weeks):
    for g in range(groups):
        s.add(Sum([If(X[w][p] == g, 1, 0) for p in range(players)]) == 3)
for p1 in range(players):
    for p2 in range(p1+1, players):
        together = Sum([If(X[w][p1] == X[w][p2], 1, 0) for w in range(weeks)])
        s.add(together <= 1)
if s.check() == sat:
